SELECT SEQ_NO seqNo ,CUSTOMER_ID customerId , CONFIG_DATE configDate , PARA_CODE paraCode , PARA_VALUE paraValue , CREATE_USER createUser , CREATE_DEPT createDept , CREATE_TIME createTime , UPDATE_USER updateUser , UPDATE_TIME updateTime FROM STL_SEC_RECON_PARA
CUSTOMER_ID = #{customerId, jdbcType=VARCHAR}
AND CONFIG_DATE = #{configDate, jdbcType=TIMESTAMP}
AND PARA_CODE = #{paraCode, jdbcType=VARCHAR}
AND PARA_VALUE = #{paraValue, jdbcType=VARCHAR}

SELECT t.CUSTOMER_ID id, t.CUSTOMER_NAME text FROM MST_CUSTOMER_INFO t WHERE t.IS_BROKER = #{isBroker, jdbcType=VARCHAR}
and t.CUSTOMER_ID = #{initValue}
AND (t.CUSTOMER_ID like CONCAT(CONCAT('%',#{search}),'%') OR t.CUSTOMER_NAME like CONCAT(CONCAT('%',#{search}),'%'))

SELECT count(1) from STL_SEC_RECON_PARA


        CUSTOMER_ID = #{customerId, jdbcType=VARCHAR}


        AND  PARA_CODE = #{paraCode, jdbcType=VARCHAR}
